export const meta = {
  name: 'code-loop',
  description: 'Native code review with fixes applied, gated by the test suites, until the diff reviews clean — then the PR',
  whenToUse: 'After the UI and functional fixes of a branch have converged and before its PR; the last stage of build-idea. Unattended: findings the reviewer can fix are applied and gated, the rest become PR comments for the human.',
  phases: [
    { title: 'Review', detail: '/code-review high --fix, then the gates' },
    { title: 'PR', detail: 'open through prm; the human merges' },
  ],
}
// Code generated by tools/gen-workflows from plugins/core/workflows/code-loop.js. DO NOT EDIT.
// Edit the flow or its fragments under plugins/lib/, then `go run ./tools/gen-workflows`.
// ---- lib/preamble.js — the lines every agent prompt starts with
// Agents already carry the repo's CLAUDE.md; these name only what a
// workflow stage needs beyond it. Keep it to contracts, never procedure —
// procedure is served by the vitrinka server (`docs {topic}`) and the CLI's
// `--help`. The two variants differ in ONE slot — where apps run: the core
// flows follow the repo's CLAUDE.md, the run-target flows (build-idea, test)
// follow the resolved `run.web` of lib/runtarget.js.
const PREAMBLE_LINES = {
  stage: 'You are one stage of a vitrinka workflow. Your final text IS the return value: return raw data for the schema, never a human-facing report.',
  checkout: 'Work in the current checkout (a worktree). Never switch branches, never stash, never touch the main checkout.',
  appsByRepo: 'Apps and test suites run where the repo\'s CLAUDE.md says — a worktree\'s devbox when one exists (`devbox run -- \'<cmd>\'`), otherwise locally; say which in `problems` when you had to fall back.',
  appsByRunTarget: 'Apps run where the run target says: the Prepare stage resolved `.claude/vitrinka-workflows.json` → `run.web` and hands you `where` (devbox | local) and `baseUrl`; `devbox` means `devbox run -- \'<cmd>\'` on this branch\'s workspace, `local` means this machine. Simulator work (iOS, Android) always runs on this machine. Say so in `problems` when you had to deviate.',
  links: 'Every vitrinka board/task link you return is the server-returned `url`, verbatim — never composed, never shortened.',
  browser: 'Browser work: onyx `browser_start(session: $CLAUDE_CODE_SESSION_ID)` first, headless, then playwright; screenshots land in `.vitrinka/mcp/` or the capture root you were given, never the repo root.',
  doors: 'When a door refuses (4xx with a diagnosis), apply the corrected call it names once; a second refusal is a `problems` entry, not a workaround.',
}

function preambleWith(apps) {
  const L = PREAMBLE_LINES
  return [L.stage, L.checkout, apps, L.links, L.browser, L.doors].join('\n')
}

const PREAMBLE = preambleWith(PREAMBLE_LINES.appsByRepo)
const RUN_TARGET_PREAMBLE = preambleWith(PREAMBLE_LINES.appsByRunTarget)

function withPreamble(prompt) {
  return PREAMBLE + '\n\n' + prompt
}

function withRunTargetPreamble(prompt) {
  return RUN_TARGET_PREAMBLE + '\n\n' + prompt
}
// `sidekick: '<agent type>'` (e.g. 'codex') hands an agent to that subagent
// type only when its call site marks it `readOnly: true` — it judges and
// writes nothing but its own output file (the ui-loop batch reviewers and
// their stall relay). A phase or label name is no proof: code-loop's
// committing fixer runs in phase 'Review' as `review:<round>`. Writers,
// committers, gates that may repair, and relays of whole CLI envelopes (a
// strict structured output refuses an over-budget payload) stay on the
// session's model. Opt-in: a session without that agent type would fail
// every call. An agent naming its own agentType keeps it.
function sidekickOptions(input, options) {
  if (!options || !options.readOnly) return options
  const { readOnly, ...rest } = options
  return input.sidekick && !rest.agentType ? Object.assign(rest, { agentType: input.sidekick }) : rest
}
// The runtime journals agent returns. Keep accounting deterministic on replay,
// share the allowance with child workflows, and bound every fan-out to four.
function workflowRun(input = {}, callAgent = agent, callWorkflow = typeof workflow === 'function' ? workflow : null) {
  const supplied = input.agentBudget || { limit: 10, used: 0 }
  const limit = supplied.limit
  let used = supplied.used
  if (!Number.isInteger(limit) || limit < 1 || limit > 10 || !Number.isInteger(used) || used < 0 || used > limit) {
    throw new Error('workflow: agentBudget must have integer limit 1..10 and used 0..limit')
  }
  const remaining = () => limit - used
  const reserve = n => {
    if (n > remaining()) throw new Error(`workflow: agent budget exhausted (${used}/${limit}); continue with the returned next args as a new run`)
  }
  return {
    remaining,
    ensureBudget: reserve,
    async agent(prompt, options) {
      reserve(1)
      used++
      return await callAgent(prompt + '\n\nWork INLINE in this agent. Never spawn subagents, workflows or background agent sessions, including from an invoked skill. The workflow script owns all delegation and the shared budget.', sidekickOptions(input, options))
    },
    async workflow(name, args) {
      if (!callWorkflow) throw new Error('workflow: no child-workflow runtime is available')
      // A child inherits the run's sidekick and ui-loop publish mode unless its own args name them.
      const inherited = {}
      for (const k of ['sidekick', 'publish']) if (input[k]) inherited[k] = input[k]
      const result = await callWorkflow(name, Object.assign(inherited, args, { agentBudget: { limit, used } }))
      if (!result || !result.agentBudget || result.agentBudget.limit !== limit || !Number.isInteger(result.agentBudget.used) || result.agentBudget.used < used || result.agentBudget.used > limit) {
        throw new Error(`workflow: ${name} returned no valid shared agent-budget receipt`)
      }
      used = result.agentBudget.used
      return result
    },
    async parallel(tasks) {
      reserve(tasks.length)
      const results = []
      for (let i = 0; i < tasks.length; i += 4) results.push(...await parallel(tasks.slice(i, i + 4)))
      return results
    },
    async serial(tasks, accept = result => result != null) {
      reserve(tasks.length)
      const results = []
      for (let i = 0; i < tasks.length; i++) {
        const result = await tasks[i]()
        results.push(result)
        if (!accept(result)) return { results, failedIndex: i }
      }
      return { results, failedIndex: null }
    },
    finish(result) { return Object.assign({}, result, { agentBudget: { limit, used } }) },
  }
}

function completionReceipt({ complete = false, problems = [], open = [], unverified = [], evidence = [] } = {}) {
  const blockers = [...problems, ...open.map(x => x.summary || x.title || String(x)), ...unverified.map(x => x.summary || x.title || String(x))]
  const status = complete && !blockers.length && evidence.length ? 'complete' : 'incomplete'
  if (status === 'incomplete' && !blockers.length) blockers.push('stage is unfinished or lacks verification evidence')
  return { v: 1, status, evidence, blockers }
}

function gatePassed(gate) {
  return !!(gate && gate.green && gate.headSha && gate.ran && gate.ran.length && Number.isInteger(gate.testsExecuted) && gate.testsExecuted > 0 && !(gate.failures || []).length)
}

function coverageProblems(routes, matrix, shots, journeys, cases, reviews, walkOnly, cards = []) {
  const problems = []
  if (!walkOnly) {
    for (const device of matrix) for (const route of routes) {
      if (!shots.some(s => s.device === device.name && s.shots.some(x => x.route === route.path))) problems.push(`missing capture: ${device.name} ${route.path}`)
      if (!cards.some(c => c.device === device.name && c.route === route.path)) problems.push(`missing published capture: ${device.name} ${route.path}`)
    }
    const read = new Set(reviews.flatMap(r => r.cardsRead || []))
    if (!cards.length || cards.some(c => !read.has(c.cardId))) problems.push('the reviewer did not read every published card')
  }
  for (const device of matrix) for (const journey of journeys) {
    if (!cases.some(c => c.title === journey.title && c.device === device.name && ['pass', 'fail'].includes(c.verdict))) problems.push(`journey not executed: ${device.name} ${journey.title}`)
  }
  return problems
}
